coding.solution:
class FormScreen {
  constructor() { this.fields = {}; this.savedState = null; }
  type(field, value) { this.fields[field] = value; }
  value(field) { return this.fields[field] || ''; }
  onPause() { this.savedState = { ...this.fields }; }
  processDeath() { this.fields = {}; }
  onResume() {
    if (Object.keys(this.fields).length === 0 && this.savedState) {
      this.fields = { ...this.savedState };
    }
  }
}
